//! Ephemeral projection of one original source/builtin callable value group.
//! Pinned register_proc inserts formal declarations at the front and implicit
//! overrides at the back, after the already registered fixed builtin value.
//! Only existing immutable nodes/metadata and checked scalar coordinates are
//! borrowed; no roster, semantic model, parser or cached answer is created.
use crate::{checker_call_facts::CallableFact,checker_effects::EffectTarget};
use dm_ir::{PackedU128,ProcedureIdentity,Resolver,SymbolId};
use dm_tree::{SemanticTree,MemberId,MemberKind,DefinitionMode,checker_builtins::CheckerBuiltinProcedureIdentity};
use std::sync::Arc;
pub(crate) struct Group<'a>{tree:&'a SemanticTree,profile:PackedU128,owner:SymbolId,name:SymbolId,head:Option<MemberId>,kind:Option<MemberKind>,sources:usize,formals:usize,builtin:Option<(CheckerBuiltinProcedureIdentity,MemberKind,Arc<dm_ir::DeclarationMeaning>)>}
impl<'a> Group<'a>{
 pub(crate) fn issue_using<E:From<String>+From<&'static str>>(tree:&'a SemanticTree,profile:PackedU128,owner:SymbolId,name:SymbolId,checkpoint:&mut impl FnMut()->Result<(),E>)->Result<Self,E>{
  let ty=tree.lookup_type(owner).ok_or("original group owner absent")?;let mut head=None;let mut source_kind=None;
  for kind in[MemberKind::Proc,MemberKind::Verb]{checkpoint()?;if let Some(id)=tree.resolve(ty,name,kind){let node=tree.member(id).ok_or("original group head absent")?;if node.owner==ty{if head.replace(id).is_some(){return Err("original source proc/verb combined chronology is not issued".into())}source_kind=Some(kind);}}}
  let mut sources=0usize;let mut formals=0usize;let mut seen_formal=false;let mut remaining=tree.members().len();let mut next=head;
  while let Some(id)=next{checkpoint()?;remaining=remaining.checked_sub(1).ok_or("original group source chain cycles")?;let node=tree.member(id).ok_or("original group member absent")?;if node.owner!=ty{break}if node.name!=name||Some(node.kind)!=source_kind{return Err("original group previous link changes name/kind".into())}if node.metadata.procedure.is_none()||node.metadata.inherited_opaque().is_some(){return Err("original group source metadata is not issued".into())}sources=sources.checked_add(1).ok_or("original group source count overflow")?;if node.definition==DefinitionMode::Declare{seen_formal=true;formals=formals.checked_add(1).ok_or("original group formal count overflow")?;}else if seen_formal{return Err("original source value group is not declaration-normalized".into())}next=node.previous;
  }
  if let Some(head)=head{if tree.member_occurrence(head)!=Some(u32::try_from(sources.checked_sub(1).ok_or("original group empty head")?).map_err(|_|"original group source ordinal overflow")?){return Err("original group source ordinal differs".into())}}
  let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("original group catalog: {e:?}"))?;let mut builtin=None;
  for row in[false,true].into_iter().filter_map(|verb|catalog.own_callable(owner,name,verb)){checkpoint()?;if builtin.is_some(){return Err("original fixed proc/verb value chronology is not issued".into())}let id=tree.checker_builtin_procedure_identity(profile,owner,name,row.kind==MemberKind::Verb,&row.metadata).map_err(|e|format!("original group builtin identity: {e:?}"))?;builtin=Some((id,row.kind,Arc::clone(&row.metadata)));}
  checkpoint()?;Ok(Self{tree,profile,owner,name,head,kind:source_kind,sources,formals,builtin})
 }
 pub(crate) fn mixed(tree:&SemanticTree,owner:SymbolId,name:SymbolId)->Result<bool,String>{let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("original mixed group catalog: {e:?}"))?;let builtin=[false,true].into_iter().any(|verb|catalog.own_callable(owner,name,verb).is_some());if !builtin{return Ok(false)}let Some(ty)=tree.lookup_type(owner)else{return Ok(false)};Ok([MemberKind::Proc,MemberKind::Verb].into_iter().any(|kind|tree.resolve(ty,name,kind).is_some_and(|id|tree.member(id).is_some_and(|row|row.owner==ty))))}
 pub(crate) fn for_target_using<E:From<String>+From<&'static str>>(tree:&'a SemanticTree,profile:PackedU128,target:EffectTarget,checkpoint:&mut impl FnMut()->Result<(),E>)->Result<Option<Self>,E>{checkpoint()?;let(owner,name)=match target{EffectTarget::Source(id)=>(id.owner,id.name),EffectTarget::Builtin(id)=>tree.with_checker_builtin_procedure(id,|row|(row.owner,row.name)).map_err(|e|format!("original target group: {e:?}"))?};if !Self::mixed(tree,owner,name)?{return Ok(None)}let group=Self::issue_using(tree,profile,owner,name,checkpoint)?;group.coordinates_using(target,checkpoint)?;Ok(Some(group))}
 pub(crate) fn observe_using<E:From<String>+From<&'static str>>(&self,resolver:&(impl Resolver+?Sized),checkpoint:&mut impl FnMut()->Result<(),E>)->Result<(),E>{use dm_ir::ResolveQuery as Q;if resolver.source_owner()!=Resolver::source_owner(self.tree){return Err("original callable group resolver is foreign".into())}for query in [Q::Ancestry(self.owner),Q::SourceDeclarationChain{owner:self.owner,name:self.name,verb:false},Q::SourceDeclarationChain{owner:self.owner,name:self.name,verb:true},Q::CheckerBuiltinProc{profile:self.profile,owner:self.owner,name:self.name,verb:false},Q::CheckerBuiltinProc{profile:self.profile,owner:self.owner,name:self.name,verb:true}]{checkpoint()?;if resolver.resolve(query)!=Resolver::resolve(self.tree,query){return Err("original callable group dependency differs".into())}}Ok(())}
 pub(crate) fn len(&self)->Result<usize,String>{self.sources.checked_add(usize::from(self.builtin.is_some())).ok_or_else(||"original combined group count overflow".into())}
 fn source_using<E:From<String>+From<&'static str>>(&self,index:usize,checkpoint:&mut impl FnMut()->Result<(),E>)->Result<(ProcedureIdentity,Arc<dm_ir::DeclarationMeaning>),E>{checkpoint()?;if index>=self.sources{return Err("original source group index outside inventory".into())}let mut current=self.head.ok_or("original source group head missing")?;let mut at=self.sources-1;loop{checkpoint()?;let row=self.tree.member(current).ok_or("original source value absent")?;if at==index{return Ok((ProcedureIdentity{owner:self.owner,name:self.name,verb:self.kind==Some(MemberKind::Verb),occurrence:u32::try_from(index).map_err(|_|"original source group index overflow")?},Arc::clone(&row.metadata)))}at=at.checked_sub(1).ok_or("original source group index underflow")?;current=row.previous.ok_or("original source group previous absent")?;}}
 fn target_using<E:From<String>+From<&'static str>>(&self,index:usize,checkpoint:&mut impl FnMut()->Result<(),E>)->Result<EffectTarget,E>{checkpoint()?;if index>=self.len()?{return Err("original combined group index outside inventory".into())}if self.builtin.is_some()&&index==self.formals{return Ok(EffectTarget::Builtin(self.builtin.as_ref().unwrap().0))}let source=if self.builtin.is_some()&&index>self.formals{index-1}else{index};Ok(EffectTarget::Source(self.source_using(source,checkpoint)?.0))}
 pub(crate) fn coordinates_using<E:From<String>+From<&'static str>>(&self,target:EffectTarget,checkpoint:&mut impl FnMut()->Result<(),E>)->Result<(usize,usize),E>{checkpoint()?;let index=match target{EffectTarget::Builtin(id)=>{if self.builtin.as_ref().map(|row|row.0)!=Some(id){return Err("original builtin target belongs to another group".into())}self.formals},EffectTarget::Source(id)=>{if id.owner!=self.owner||id.name!=self.name||Some(if id.verb{MemberKind::Verb}else{MemberKind::Proc})!=self.kind{return Err("original source target belongs to another group".into())}let index=usize::try_from(id.occurrence).map_err(|_|"original source target ordinal overflow")?;if self.source_using(index,checkpoint)?.0!=id{return Err("original source target ordinal differs".into())}if self.builtin.is_some()&&index>=self.formals{index.checked_add(1).ok_or("original source combined index overflow")?}else{index}}};Ok((index,self.len()?))}
 pub(crate) fn winner_using<E:From<String>+From<&'static str>>(&self,checkpoint:&mut impl FnMut()->Result<(),E>)->Result<Option<CallableFact>,E>{checkpoint()?;let count=self.len()?;if count==0{return Ok(None)}self.fact_using(self.target_using(count-1,checkpoint)?,checkpoint).map(Some)}
 pub(crate) fn fact_using<E:From<String>+From<&'static str>>(&self,target:EffectTarget,checkpoint:&mut impl FnMut()->Result<(),E>)->Result<CallableFact,E>{checkpoint()?;self.coordinates_using(target,checkpoint)?;match target{EffectTarget::Source(id)=>{let(identity,metadata)=self.source_using(id.occurrence as usize,checkpoint)?;Ok(CallableFact::Source{identity,metadata})},EffectTarget::Builtin(_)=>{let(_,_,metadata)=self.builtin.as_ref().ok_or("original builtin fact absent")?;Ok(CallableFact::CheckerBuiltin{declaring_owner:self.owner,name:self.name,metadata:Arc::clone(metadata)})}}}
 pub(crate) fn parent_using<E:From<String>+From<&'static str>>(&self,target:EffectTarget,resolver:&(impl Resolver+?Sized),checkpoint:&mut impl FnMut()->Result<(),E>)->Result<Option<EffectTarget>,E>{checkpoint()?;self.observe_using(resolver,checkpoint)?;let(index,_)=self.coordinates_using(target,checkpoint)?;if index>0{return self.target_using(index-1,checkpoint).map(Some)}let owner=self.tree.lookup_type(self.owner).ok_or("original parent group owner absent")?;let Some(parent)=self.tree.parent(owner)else{return Ok(None)};let path=self.tree.type_node(parent).ok_or("original parent type absent")?.path;let fact=crate::checker_call_facts::callable_any_using(self.tree,resolver,self.profile,path,self.name,checkpoint)?;if matches!(fact,CallableFact::Missing){Ok(None)}else{Ok(Some(crate::checker_effects::callable_target(self.tree,self.profile,&fact)?))}}
 pub(crate) fn visit_source_values_using<E:From<String>+From<&'static str>>(&self,checkpoint:&mut impl FnMut()->Result<(),E>,emit:&mut impl FnMut(ProcedureIdentity,bool)->Result<(),E>)->Result<(),E>{
  let verb=if self.formals!=0{self.kind==Some(MemberKind::Verb)}else{self.builtin.as_ref().is_some_and(|(_,kind,_)|*kind==MemberKind::Verb)};
  for index in 0..self.len()?{checkpoint()?;if let EffectTarget::Source(identity)=self.target_using(index,checkpoint)?{emit(identity,verb)?;}}Ok(())
 }
 // Tests exercise the same DATA projection without an operation coordinator.
 #[cfg(test)]pub(crate) fn issue(tree:&'a SemanticTree,profile:PackedU128,owner:SymbolId,name:SymbolId)->Result<Self,String>{Self::issue_using(tree,profile,owner,name,&mut||Ok(()))}
 #[cfg(test)]pub(crate) fn source(&self,index:usize)->Result<(ProcedureIdentity,Arc<dm_ir::DeclarationMeaning>),String>{self.source_using(index,&mut||Ok(()))}
 #[cfg(test)]pub(crate) fn coordinates(&self,target:EffectTarget)->Result<(usize,usize),String>{self.coordinates_using(target,&mut||Ok(()))}
 #[cfg(test)]pub(crate) fn fact(&self,target:EffectTarget)->Result<CallableFact,String>{self.fact_using(target,&mut||Ok(()))}
 #[cfg(test)]pub(crate) fn parent(&self,target:EffectTarget,resolver:&(impl Resolver+?Sized))->Result<Option<EffectTarget>,String>{self.parent_using(target,resolver,&mut||Ok(()))}

}

